esqlQuery.esql:
TS metrics-temporal.cloud_metrics.otel-*
// total_action_count is a rate (actions/s); action_limit is the provisioned cap (actions/s)
// action_limit only counts is_background=false actions (Temporal Cloud OpenMetrics)
// MAX ensures the limit value is the current provisioned limit
| STATS avg_actions = SUM(AVG_OVER_TIME(metrics.temporal_cloud_v1_total_action_count)) WHERE attributes.is_background == "false",
        action_limit = MAX(AVG_OVER_TIME(metrics.temporal_cloud_v1_action_limit))
    BY attributes.temporal_namespace
// Exclude namespaces with no limit data
| WHERE action_limit > 0
// Compute utilisation percentage
| EVAL utilization_pct = ROUND(avg_actions / action_limit * 100.0, 2)
// Alert at 80% to provide headroom before throttling begins
| WHERE utilization_pct > 80
| SORT utilization_pct DESC
| LIMIT 10
